import {configureViewer,setViewerSource} from '../../viewer-runtime.js?v=20261119';
const viewer = document.getElementById('growth-model');
const poster = document.getElementById('growth-poster');
const play = document.getElementById('growth-play');
const reset = document.getElementById('growth-reset');
const time = document.getElementById('growth-time');
const status = document.getElementById('growth-status');
const nativeAR = document.getElementById('growth-quicklook');
const browserAR = document.getElementById('growth-ar');
const count = document.getElementById('growth-count');
const cells = document.getElementById('growth-cells');
const round = document.getElementById('growth-round');
const isQuickLook = nativeAR.relList.supports('ar');
nativeAR.hidden = !isQuickLook;
configureViewer(viewer,{actions:play.parentElement,status,title:'HeLa culture growth',src:viewer.dataset.src,arButton:browserAR,androidHint:'On Android, load the culture with Play growth, then choose View in AR on a compatible phone.'});

let ready = false;
let playing = false;
let events = [];
let updateId = 0;
let preparation;

function sync() {
  const seconds = viewer.currentTime || 0;
  const divisions = events.filter(event => event.split <= seconds).length;
  const currentRound = events.reduce((latest,event) => event.start <= seconds ? event.round : latest,0);
  const nextCells = (2 + divisions) + ' cells';
  const nextRound = currentRound ? 'Round ' + currentRound + ' of 10' : 'Starting culture';
  if (cells.textContent !== nextCells) cells.textContent = nextCells;
  if (round.textContent !== nextRound) round.textContent = nextRound;
  time.value = Math.round(1000 * seconds / viewer.duration);
  time.setAttribute('aria-valuetext', nextRound + ', ' + nextCells);
  if (playing) updateId = requestAnimationFrame(sync);
}

function pause() {
  viewer.pause();
  playing = false;
  cancelAnimationFrame(updateId);
  play.textContent = viewer.currentTime >= viewer.duration - .04 ? 'Replay growth' : 'Play growth';
  sync();
}

async function prepare() {
  if (ready) return;
  if (preparation) return preparation;
  setViewerSource(viewer,viewer.dataset.src);
  play.disabled = true;
  status.textContent = 'Loading the 3D cell culture…';
  preparation = Promise.all([
    import('/cr8zar/hela/assets/model-viewer.min.js').then(() => customElements.whenDefined('model-viewer')),
    fetch('/cr8zar/hela/assets/hela-growth-v19.json').then(response => {
      if (!response.ok) throw Error('Growth timeline unavailable');
      return response.json();
    }),
  ]).then(([, timeline]) => {
    events = timeline.events;
    return new Promise((resolve, reject) => {
      if (viewer.loaded) return resolve();
      viewer.addEventListener('load', resolve, {once:true});
      viewer.addEventListener('error', reject, {once:true});
      viewer.dismissPoster();
    });
  }).then(() => {
    if (!viewer.availableAnimations.length) throw Error('Growth animation unavailable');
    ready = true;
    poster.hidden = true;
    count.hidden = false;
    play.disabled = reset.disabled = time.disabled = false;
    browserAR.hidden = isQuickLook || !viewer.canActivateAR;
    status.textContent = '';
    sync();
  }).catch(error => {
    preparation = undefined;
    play.disabled = false;
    status.textContent = 'The 3D culture could not load. You can still see the final culture above.';
    throw error;
  });
  return preparation;
}

play.addEventListener('click', async () => {
  if (playing) return pause();
  try {
    await prepare();
    if (viewer.currentTime >= viewer.duration - .04) viewer.currentTime = 0;
    viewer.play({repetitions:1});
    playing = true;
    play.textContent = 'Pause growth';
    sync();
  } catch {
    // prepare() keeps the final culture preview available if loading fails.
  }
});
reset.addEventListener('click', () => {
  viewer.currentTime = 0;
  pause();
});
time.addEventListener('input', () => {
  viewer.currentTime = Number(time.value) / 1000 * viewer.duration;
  pause();
});
viewer.addEventListener('finished', pause);
viewer.addEventListener('viewer-backgrounded',pause);
browserAR.addEventListener('click', async () => {
  try {
    await viewer.activateAR();
    viewer.play({repetitions:1});
  } catch {
    status.textContent = 'AR could not open. You can still play the 3D model here.';
  }
});

import {connectTrackedModel} from '/cr8zar/tracked-model.js?v=20261119';
import {configureViewer,setViewerSource} from '/cr8zar/viewer-runtime.js?v=20261119';
import {mountARAssist} from '/cr8zar/ar-assist.js?v=16';
import {opacityAt} from './dissolve.js';
const data = {
  interphase: {
    title:"Interphase", topic:"Cell structure",
    copy:"This cell is spread out on the surface where it grows. Its nucleus is intact. During interphase the cell does its usual work and copies its DNA before division.",
    question:"Which structure controls what enters and leaves?", answer:"The plasma membrane.",
    motion:"Follow the small lysosome as it moves through the cytoplasm.",
    parts:[
      ["Plasma membrane","A flexible boundary that controls which substances cross.","Membrane transport"],
      ["Nucleus","Holds most of the cell’s DNA. Its envelope has pores that regulate traffic.","DNA and gene expression"],
      ["Nucleolus","A region inside the nucleus where ribosome assembly begins.","Ribosome assembly"],
      ["Mitochondria","Use energy from food molecules to make much of the cell’s ATP.","Cellular respiration"],
      ["Rough ER","The sheets carry ribosomes that make proteins.","Protein synthesis"],
      ["Smooth ER","The smooth tubules help make lipids.","Lipid synthesis"],
      ["Golgi apparatus","Modifies, sorts and sends proteins and lipids to their destinations.","Vesicle transport"],
      ["Centrosome","The paired centrioles sit in a region that organizes microtubules.","Cytoskeleton"],
      ["Lysosomes","These compartments break down and recycle cellular material.","Cellular recycling"],
      ["Peroxisomes","These compartments help break down fatty acids.","Cell metabolism"],
    ]},
  prophase:{
    title:"Prophase", topic:"Mitosis",
    copy:"The cell begins to round up. Chromatin condenses into visible chromosomes, the nucleolus disperses, and the centrosomes move apart. Play the transition into prometaphase to see the nuclear envelope break apart and the ER reorganize.",
    question:"What happens to chromatin during prophase?",
    answer:"It condenses into visible chromosomes.",
    motion:"Watch the chromosomes become more distinct as the nuclear envelope breaks apart.",
    parts:[
      ["Condensing chromosomes","Each duplicated chromosome contains two sister chromatids.","Chromosome condensation"],
      ["Nuclear envelope","The translucent envelope surrounds the chromosomes at first, then breaks apart in prometaphase.","Nuclear organization"],
      ["Centrosomes","These structures move apart as the mitotic spindle begins to form.","Spindle formation"],
      ["Mitochondria","Mitochondria remain visible in the cytoplasm as division begins.","Organelle inheritance"],
    ]},
  metaphase:{
    title:"Metaphase", topic:"Mitosis",
    copy:"The cell has rounded up. Duplicated chromosomes line up near the middle, attached to fibers from opposite ends of the spindle.",
    question:"Where do chromosomes line up in metaphase?",answer:"Near the middle, at the metaphase plate.",
    motion:"The small movements illustrate how chromosomes adjust near the middle. Their movement to opposite ends happens later, in anaphase.",
    parts:[
      ["Duplicated chromosomes","Each contains two DNA copies, called sister chromatids, held together until separation.","DNA replication and inheritance"],
      ["Spindle fibers","Microtubules attach to chromosomes and help move their copies to opposite sides.","Cytoskeleton and mitosis"],
      ["Centrosome","Organizes spindle microtubules at each pole.","Chromosome separation"],
      ["Mitochondria","Mitochondria remain in the cytoplasm during division.","Organelle inheritance"],
      ["Golgi vesicles","Fragments from the Golgi stack are dispersed through the cytoplasm.","Organelle inheritance"],
      ["Remodeled ER","Short tubules represent the reorganized ER around the spindle.","Endomembrane system"],
    ]},
  anaphase:{
    title:"Anaphase", topic:"Mitosis",
    copy:"Sister chromatids separate and move toward opposite spindle poles. Each separated chromatid is now a daughter chromosome.",
    question:"What moves toward opposite poles?", answer:"The separated sister chromatids, now daughter chromosomes.",
    motion:"Watch the two sets move apart as the fibers between them and the poles shorten.",
    parts:[
      ["Daughter chromosomes","The two sets move toward opposite sides of the cell.","Chromosome segregation"],
      ["Kinetochore microtubules","These fibers shorten as the chromosomes move poleward.","Mitotic spindle"],
      ["Spindle pole","One of two ends organizing the spindle.","Centrosomes"],
    ]},
  cytokinesis:{
    title:"Cytokinesis", topic:"Cell division",
    copy:"Two nuclei have formed around separated sets of chromosomes. A thin bridge still connects the daughter cells. When the bridge is cut, the cells fully separate.",
    question:"What still joins the daughter cells?",answer:"The intercellular bridge, which contains the midbody.",
    motion:"Watch the bridge narrow and the two daughter cells separate.",
    parts:[
      ["Daughter nucleus","A new nuclear envelope surrounds each separated set of chromosomes.","End of nuclear division"],
      ["Intercellular bridge","A narrow link remains as the cell finishes dividing its cytoplasm.","Cytokinesis"],
      ["Midbody","A dense structure inside the bridge that helps organize the final cut.","Abscission, the last step of cytokinesis"],
      ["Rough ER","Ribosome-covered sheets reform around each daughter nucleus.","Endomembrane system"],
      ["Lysosomes","Each daughter cell inherits lysosomes.","Organelle inheritance"],
    ]},
  'full-cycle':{
    title:"Full Cycle", topic:"Cell division",
    copy:"Watch the nucleolus disperse and the nuclear envelope break down. Golgi vesicles and remodeled ER remain visible during division, while mitochondria and peroxisomes move into both daughter cells.",
    question:"When do the daughter nuclei reform?", answer:"During telophase, after the chromosomes have moved toward opposite poles.",
    motion:"Rotate the cutaway while the cycle plays, or pause to inspect a stage.",
    parts:[
      ["Interphase","The cell grows and copies its DNA before mitosis.","Cell preparation"],
      ["Prophase and prometaphase","Chromosomes condense, the nuclear envelope breaks down, and the spindle attaches.","Spindle formation"],
      ["Metaphase and anaphase","Chromosomes line up, then the sister chromatids move apart.","Chromosome segregation"],
      ["Telophase and cytokinesis","Nuclei and organelle networks reassemble in both daughter cells before the bridge is cut.","Formation of daughter cells"],
      ["Centrosome","The pair of short cylinders represents the centrioles. The centrosomes organize the spindle microtubules at opposite poles.","Microtubule organization"],
      ["Lysosomes","The small round compartments break down and recycle cellular material.","Cellular recycling"],
      ["Ribosomes on rough ER","The dark dots on the rough ER make proteins.","Protein synthesis"],
      ["Nuclear speckles","These small membraneless bodies disperse around the time the nuclear envelope breaks down.","Nuclear organization"],
    ]},
};
const keys=Object.keys(data);
const cycleStages = [
  [0, 'Organelle overview'], [36 / 24, 'Interphase'], [64 / 24, 'Prophase'], [112 / 24, 'Prometaphase'],
  [248 / 24, 'Metaphase'], [302 / 24, 'Anaphase'], [386 / 24, 'Telophase'],
  [434 / 24, 'Cytokinesis'], [513 / 24, 'Abscission'], [549 / 24, 'Two HeLa daughter cells'],
];
const assetVersions={anaphase:17,prophase:18};
const assetPath=key=>'/cr8zar/hela/assets/'+key+'-v'+(assetVersions[key]??15);
const quickLookPath=key=>key==='full-cycle'?'/cr8zar/hela/assets/full-cycle-v18.usdz':assetPath(key)+'.usdz';
const oneShotPhases=new Set(['prophase','anaphase','cytokinesis','full-cycle']);
const q=(s)=>document.querySelector(s);
const viewer=q('#viewer'), fallback=q('#fallback'), marker=q('#target'), status=q('#status'), ar=q('#ar'), reset=q('#reset');
const launch=q('#camera-launch');
configureViewer(viewer,{actions:q('.toolrow'),status,arButton:ar,androidHint:'On Android, use View in your space or Camera AR with BridgeAssist for the animated cell phases.'});
const cycleStage=q('#cycle-stage');
const isQuickLook=document.createElement('a').relList.supports('ar');
const cameraEntry=new URL(location.href).searchParams.get('camera')==='1';
let launchLink;
if (isQuickLook) {
  launchLink=document.createElement('a');
  launchLink.rel='ar';
  launchLink.className='hela-quicklook';
  launchLink.setAttribute('aria-label','View selected phase in AR');
  const icon=document.createElement('img');
  icon.src='/cr8zar/ar-icon.svg';
  icon.alt='';
  launchLink.append(icon);
  launch.append(launchLink);
  launch.hidden=false;
}
if (cameraEntry) document.body.classList.add('camera-entry');
let active='interphase', motion=false, ready=false, failed=false, api=false, serial=0, labels=[];
let tick=0, completed=false;
let organelleMaterials=[];
let selectedPartIndex=-1, hotspotPosition='';
const dissolvePhases=new Set(['prophase','full-cycle']);
const dissolveRequests=new Map();
function getDissolveCurves(phase){
  if(!dissolvePhases.has(phase)) return undefined;
  if(!dissolveRequests.has(phase)){
    dissolveRequests.set(phase,fetch(assetPath(phase)+'.dissolve.json').then(response=>{
      if(!response.ok) throw Error('Could not load the dissolve timings');
      return response.json();
    }).catch(()=>{
      dissolveRequests.delete(phase);
      return null;
    }));
  }
  return dissolveRequests.get(phase);
}
function updateOrganelleFades(seconds){
  for(const entry of organelleMaterials){
    const alpha=opacityAt(entry.keys,seconds);
    if(entry.alpha===alpha || (alpha>0 && alpha<1 && Math.abs(entry.alpha-alpha)<.005)) continue;
    entry.alpha=alpha;
    entry.material.pbrMetallicRoughness.setBaseColorFactor([...entry.color,alpha]);
    const mode=alpha===1 ? 'OPAQUE' : 'BLEND';
    if(entry.material.getAlphaMode()!==mode) entry.material.setAlphaMode(mode);
  }
}
async function bindOrganelleMaterials(){
  if(!dissolvePhases.has(active)) return;
  const phaseSerial=serial;
  const curves=await getDissolveCurves(active);
  if(!curves || phaseSerial!==serial) return;
  organelleMaterials=(viewer.model?.materials ?? [])
    .filter(material=>curves[material.name])
    .map(material=>({material,keys:curves[material.name],
      color:material.pbrMetallicRoughness.baseColorFactor.slice(0,3),alpha:-1}));
  updateOrganelleFades(viewer.currentTime||0);
}
function frameSpecimen(){
  const division=active!=='interphase';
  viewer.maxCameraOrbit=division?'auto 174deg 1.05m':'auto 174deg 190%';
  viewer.minCameraOrbit=division?'auto 10deg .20m':'auto 10deg 48%';
  viewer.cameraOrbit=division?'0deg 61deg .48m':'0deg 61deg 105%';
  viewer.cameraTarget=division?'0m .051m 0m':'auto auto auto';
  viewer.fieldOfView='33deg';
  viewer.jumpCameraToGoal();
}
function updatePlayback(){
  const seconds=ready ? viewer.currentTime || 0 : 0;
  if(ready) updateOrganelleFades(seconds);
  cycleStage.hidden=active!=='full-cycle';
  if(!cycleStage.hidden){
    let stage=cycleStages[0][1];
    for(const [start,title] of cycleStages){
      if(seconds<start) break;
      stage=title;
    }
    if(cycleStage.textContent!==stage) cycleStage.textContent=stage;
  }
  if(active==='anaphase' && selectedPartIndex>=0 && !marker.hidden) movePartMarker(selectedPartIndex,seconds);
  if(active==='prophase' && selectedPartIndex===1) marker.hidden=!ready || seconds>=3;
  if(motion && ready && (dissolvePhases.has(active) || active==='anaphase')) tick=requestAnimationFrame(updatePlayback);
}
function setStatus(){
  status.textContent=failed ? '3D is unavailable. The illustration and anatomy list are still here.' :
    !ready ? 'Loading the 3D model…' : motion ? data[active].motion :
    viewer.canActivateAR ? '' : 'AR is available on supported phones.';
}
function renderMotion(){
  document.querySelectorAll('.motion-toggle').forEach(b=>{
    const action=active==='full-cycle'?'cycle':'motion';
    b.textContent=motion?'Pause motion':(completed?'Replay ':'Play ')+action;
    b.setAttribute('aria-pressed',motion);
    b.disabled=!ready || viewer.availableAnimations.length===0;
  });
  if(ready){
    if(motion) viewer.play(oneShotPhases.has(active) ? {repetitions:1} : undefined);
    else viewer.pause();
  }
  cancelAnimationFrame(tick);
  updatePlayback();
  setStatus();
}
function selectPart(button, i, toggle=true){
  const same=button.getAttribute('aria-pressed')==='true';
  document.querySelectorAll('#parts button').forEach(b=>b.setAttribute('aria-pressed','false'));
  const selected=!toggle || !same;
  selectedPartIndex=selected?i:-1;
  button.setAttribute('aria-pressed',String(selected));
  const pos=labels[i]?.targetMeters;
  const passedBridge=active==='cytokinesis'&&[1,2].includes(i)&&viewer.currentTime>1.58;
  const passedEnvelope=active==='prophase'&&i===1&&viewer.currentTime>=3;
  marker.hidden=!selected || !pos || !ready || passedBridge || passedEnvelope;
  marker.textContent=data[active].parts[i][0];
  if(pos) movePartMarker(i,viewer.currentTime||0);
}
function movePartMarker(index,seconds){
  const {targetMeters,targetFrames,targetFps}=labels[index];
  const frame=targetFrames?Math.min(targetFrames.length-1,Math.round(seconds*targetFps)):0;
  const position=(targetFrames?.[frame]??targetMeters).map(value=>value+'m').join(' ');
  if(position===hotspotPosition) return;
  hotspotPosition=position;
  marker.dataset.position=position;
  if(api) viewer.updateHotspot({name:'hotspot-selected',position});
}
function showSelectedPart(){
  const buttons=[...q('#parts').querySelectorAll('button')];
  const index=buttons.findIndex(button=>button.getAttribute('aria-pressed')==='true');
  if(index>=0) selectPart(buttons[index],index,false);
}
function changePhase(k,{updateURL=true}={}){
  if(!keys.includes(k)) return;
  const id=++serial; active=k; const d=data[k];
  completed=false;
  organelleMaterials=[];
  q('#cycle-organelle-note').hidden=k!=='full-cycle';
  motion=k==='full-cycle'&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.querySelectorAll('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.phase===k)));
  q('#phase-meta').textContent=d.topic; q('#phase-title').textContent=d.title;
  q('#phase-copy').textContent=d.copy;
  q('#question').textContent=d.question;q('#answer').textContent=d.answer;q('#check').open=false;
  q('#parts').replaceChildren(...d.parts.map(([name,desc,topic],i)=>{
    const interactive=k!=='full-cycle';
    const button=document.createElement(interactive?'button':'div');
    button.className=interactive?'part':'part cycle-detail';
    if(interactive){button.type='button';button.setAttribute('aria-pressed','false');}
    const body=document.createElement('span'), title=document.createElement('strong'), summary=document.createElement('span'), topicEl=document.createElement('small');
    title.textContent=name;summary.textContent=desc;topicEl.textContent=topic;
    body.append(title,summary,topicEl);button.append(body);
    if(interactive) button.addEventListener('click',()=>selectPart(button,i));
    return button;
  }));
  marker.hidden=true;labels=[];selectedPartIndex=-1;hotspotPosition='';
  const asset=assetPath(k);
  if(k!=='full-cycle') fetch(asset+'.labels.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(v=>{
    if(id!==serial) return;
    labels=v;
    showSelectedPart();
  }).catch(()=>{});
  const src=asset+'.glb';
  const iosSrc=quickLookPath(k);
  if(launchLink) launchLink.href=iosSrc;
  if(viewer.getAttribute('src')!==src){ready=false;failed=false;reset.disabled=true;viewer.classList.remove('ready');viewer.setAttribute('ios-src',iosSrc);setViewerSource(viewer,src);}
  viewer.setAttribute('alt',k==='full-cycle'?'Animated HeLa cell division':'3D teaching model of a HeLa cell in '+d.title.toLowerCase());
  fallback.src=asset+'.png';fallback.alt='Cutaway illustration of '+d.title.toLowerCase();
  if(updateURL){const u=new URL(location.href); if(k===keys[0])u.searchParams.delete('phase');else u.searchParams.set('phase',k);history.replaceState(null,'',u);}
  renderMotion();
}
viewer.addEventListener('load',()=>{
  ready=true;failed=false;viewer.classList.add('ready');reset.disabled=false;
  ar.hidden=isQuickLook||!viewer.canActivateAR;
  bindOrganelleMaterials();
  frameSpecimen();
  showSelectedPart();
  renderMotion();
});
viewer.addEventListener('error',()=>{failed=true;ready=false;viewer.classList.remove('ready');renderMotion();});
viewer.addEventListener('viewer-suspended',()=>{
  ready=false;reset.disabled=true;organelleMaterials=[];
  cancelAnimationFrame(tick);
});
viewer.addEventListener('viewer-backgrounded',()=>{motion=false;renderMotion();});
const phaseAction=(_request,match)=>{
  const key=match[3].replaceAll(' ','-');
  if(!keys.includes(key)) return null;
  changePhase(key);
  return 'I switched to '+data[key].title+'.';
};
const xrHelp=mountARAssist(q('#xr-assist'),{
  intro:'Ask about HeLa or say “switch to metaphase.”',
  actions:{phase:phaseAction}
});
mountARAssist(q('#hela-assist'),{
  intro:'Ask about HeLa, say “switch to metaphase,” or get help opening AR.',
  actions:{phase:phaseAction,reset:()=>{if(!ready)return 'The model is still loading.';reset.click();return 'I reset the 3D view.';}}
});
viewer.addEventListener('ar-status',(event)=>{
  const s=event.detail.status;
  if(s==='not-presenting'||s==='failed')xrHelp.close();
  q('#xr-status').textContent=s==='object-placed' ? 'Drag to move · Twist to turn · Pinch to resize' : 'Move your phone slowly to find a surface. Tap to place.';
  if(s==='failed')status.textContent='AR could not start. You can keep using the 3D model.';
});
viewer.addEventListener('ar-tracking',(event)=>{
  if(event.detail.status==='not-tracking')q('#xr-status').textContent='Surface tracking paused. Move slowly and aim at a well-lit surface.';
  else if(viewer.getAttribute('ar-status')==='object-placed')q('#xr-status').textContent='Drag to move · Twist to turn · Pinch to resize';
});
document.querySelectorAll('[data-phase]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.phase!==active)changePhase(b.dataset.phase)}));
viewer.addEventListener('finished',()=>{
  if(!oneShotPhases.has(active) || !ready) return;
  if(active==='cytokinesis') marker.hidden=true;
  motion=false;
  completed=true;
  renderMotion();
});
document.querySelectorAll('.motion-toggle').forEach(button=>button.addEventListener('click',()=>{
  if(completed) viewer.currentTime=0;
  if(active==='cytokinesis') marker.hidden=true;
  completed=false;
  motion=!motion;
  renderMotion();
}));
ar.addEventListener('click',async()=>{try{await viewer.activateAR();}catch{status.textContent='AR could not start. You can keep using the 3D model.'}});
reset.addEventListener('click',frameSpecimen);
const initial=new URL(location.href).searchParams.get('phase');
changePhase(keys.includes(initial)?initial:'interphase',{updateURL:false});
const choices=Object.fromEntries(keys.map(key=>[key,{title:data[key].title,src:assetPath(key)+'.glb',
  dissolveCurves:dissolvePhases.has(key)?()=>getDissolveCurves(key):undefined}]));
connectTrackedModel(q('#hela-tracked'),{
  choices,getKey:()=>active,onSelect:changePhase,phaseAction:true,preview:viewer,
  lighting:{
    sky:0xe8dcff, ground:0x652639, ambient:1.05,
    lamps:[
      {color:0xff9cae,intensity:2.25,position:[-4,6,4]},
      {color:0xb98aff,intensity:2.1,position:[3,4,-4]},
      {color:0xe9dcff,intensity:.95,position:[3,2,3]},
    ],
  },
});
customElements.whenDefined('model-viewer').then(()=>{api=true; if(viewer.loaded && !ready){ready=true;viewer.classList.add('ready');reset.disabled=false;ar.hidden=isQuickLook||!viewer.canActivateAR;bindOrganelleMaterials();frameSpecimen();renderMotion();}}).catch(()=>{failed=true;setStatus()});

// Keep GLB parsing serial and discard superseded selections before attaching them.
const cancelled = () => new DOMException('A newer model was selected','AbortError');
export class LatestModelQueue {
  constructor(load,release) {
    this.load=load; this.release=release; this.version=0; this.closed=false;
  }
  select(value) {
    if (this.closed) return Promise.reject(cancelled());
    const promise=new Promise((resolve,reject) => {
      this.pending?.reject(cancelled());
      this.current?.reject(cancelled());
      this.pending={value,resolve,reject,version:++this.version};
    });
    this.controller?.abort();
    this.run();
    return promise;
  }
  async run() {
    if (this.running) return;
    this.running=true;
    try {
      while (this.pending && !this.closed) {
        const job=this.pending;
        this.pending=undefined; this.current=job;
        const controller=new AbortController(); this.controller=controller;
        try {
          const result=await this.load(job.value,controller.signal);
          if (this.closed || job.version!==this.version) {
            this.release(result);
            job.reject(cancelled());
          } else job.resolve(result);
        } catch (error) {job.reject(error);}
        finally {if(this.current===job)this.current=undefined;}
      }
    } finally {this.running=false;this.controller=undefined;}
  }
  close() {
    this.closed=true; this.version++;
    this.pending?.reject(cancelled()); this.pending=undefined;
    this.current?.reject(cancelled()); this.controller?.abort();
  }
}

import {currentItemId,hasQR,qrAsset} from './qr-tools.mjs';
import {connectScanner} from './scanner.js';
import {configureViewer,setViewerSource,disposeViewer} from './viewer-runtime.js?v=20261119';

const $ = id => document.getElementById(id);
const items = await fetch('/data/cr8zar.json').then(r => {
  if (!r.ok) throw Error('Library unavailable');
  return r.json();
}).catch(() => []);
if (!items.length) $('title').textContent = 'The library could not load. Try refreshing.';
$('scan').disabled = !items.length;
const library = new Map(items.map(item => [item.id, item]));
const normal = s => s.toLowerCase().normalize('NFKD').replace(/\p{Diacritic}/gu, '');
let current;
let viewerImport;
const phone = matchMedia('(max-width: 720px)');

function el(tag, text, cls) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  if (cls) node.className = cls;
  return node;
}
function link(text, href, cls) {
  const a = el('a', text, cls);
  a.href = href;
  return a;
}
function itemHref(id) {
  return '/cr8zar/?item=' + encodeURIComponent(id);
}
function drawResults() {
  const words = normal($('search').value).trim().split(/\s+/).filter(Boolean);
  const kind = $('kind').value;
  const topic = $('topic').value;
  const found = items.filter(item => {
    const text = normal([item.title,item.topic,item.description,...(item.courses || []),...(item.tags || [])].join(' '));
    return (!kind || (kind === 'model' ? item.kind === 'Model' : item.kind === kind)) &&
      (!topic || item.topic === topic || item.tags?.includes(topic)) && words.every(w => text.includes(w));
  });
  $('count').textContent = found.length + ' of ' + items.length + ' resources';
  $('results').replaceChildren(...found.map(item => {
    const a = link(item.title,itemHref(item.id),'result');
    a.append(el('small',item.kind + ' · ' + item.topic));
    if (item.id === current?.id) a.setAttribute('aria-current','page');
    a.addEventListener('click', event => {
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      event.preventDefault();
      show(item, true);
    });
    return a;
  }));
}
function quickLook(asset) {
  const a = link('', '/cr8zar/models/' + asset + '.usdz','primary quicklook');
  a.rel = 'ar';
  a.setAttribute('aria-label','View in AR');
  const image = el('img');
  image.src = '/cr8zar/ar-icon.svg';
  image.alt = '';
  a.append(image);
  return a;
}
function model(item) {
  const v = el('model-viewer');
  setViewerSource(v,'/cr8zar/models/' + item.asset + '.glb');
  v.setAttribute('ios-src','/cr8zar/models/' + item.asset + '.usdz');
  if (item.poster) {
    v.setAttribute('poster',item.poster);
    v.setAttribute('loading','eager');
    v.classList.add('refined-model');
  }
  v.setAttribute('alt',item.title + ', interactive teaching model');
  v.setAttribute('camera-controls','');
  v.setAttribute('touch-action','pan-y');
  v.setAttribute('camera-orbit',item.cameraOrbit || '32deg 62deg auto');
  v.setAttribute('interaction-prompt','none');
  v.setAttribute('ar','');
  v.setAttribute('ar-modes','webxr scene-viewer quick-look');
  const custom = el('span');
  custom.slot = 'ar-button';
  v.append(custom);
  $('specimen').append(v);
  if (item.poster) {
    const controls = el('div','','actions');
    const play = el('button','Play animation','primary');
    play.type = 'button';
    play.hidden = !item.motion;
    play.disabled = true;
    const status = el('p','','topic');
    status.setAttribute('role','status');
    controls.append(play);
    $('specimen').prepend(controls);
    $('specimen').append(status);
    if (item.video) {
      const fallback = el('details','','model-video');
      fallback.append(el('summary',item.videoTitle || 'Watch the video instead'));
      const video = el('video');
      video.controls = true;
      video.playsInline = true;
      video.preload = 'none';
      video.src = item.video;
      video.poster = item.videoPoster || item.poster;
      video.setAttribute('aria-label',item.videoTitle || item.title + ' animation');
      fallback.append(video,el('p',item.videoDescription || 'Microtubules grow from the centrosome. Next, an mRNA message leaves the nucleus. A ribosome reads the message, and tRNAs bring amino acids to build a protein chain.'));
      fallback.addEventListener('toggle',() => {
        if (fallback.open) v.pause();
        else video.pause();
        syncPlay();
      });
      $('specimen').append(fallback);
      v.addEventListener('error',() => {fallback.open = true;});
    }
    function syncPlay() {
      play.textContent = v.paused ? 'Play animation' : 'Pause animation';
    }
    v.addEventListener('load',() => {
      play.hidden = !v.availableAnimations.length;
      play.disabled = play.hidden;
      status.textContent = play.hidden
        ? 'Drag to rotate. Pinch to zoom.'
        : 'Drag to rotate. Pinch to zoom. Animation plays here in 3D.';
    });
    v.addEventListener('finished',syncPlay);
    play.addEventListener('click',() => {
      if (v.paused) {
        if (v.currentTime >= v.duration - .05) v.currentTime = 0;
        v.play({repetitions:1});
      } else v.pause();
      syncPlay();
    });
  }
  const native = document.createElement('a').relList.supports('ar');
  const ar = native ? quickLook(item.asset) : el('button','View in AR','primary');
  if (!native) {
    ar.type = 'button';
    ar.hidden = true;
    const sync = () => {ar.hidden = !v.canActivateAR;};
    v.addEventListener('load',sync);
    ar.addEventListener('click',() => {
      v.activateAR().catch(() => {$('source').textContent = 'AR could not open. You can still rotate the 3D model here.';});
    });
  }
  $('actions').append(ar);
  configureViewer(v,{actions:$('actions'),status:$('source'),title:item.title,arButton:native?undefined:ar});
  viewerImport ||= import('/cr8zar/hela/assets/model-viewer.min.js');
  viewerImport.catch(() => {$('source').textContent = 'The interactive 3D viewer could not load.';});
  v.addEventListener('error',() => {$('source').textContent = 'The interactive 3D model could not load.';});
}
function show(item, navigate = false) {
  current = item;
  if (navigate) history.pushState(null, '', itemHref(item.id));
  $('type').textContent = item.kind + ' · ' + item.topic;
  $('title').textContent = item.title;
  $('description').textContent = item.description;
  $('actions').replaceChildren();
  for(const old of $('specimen').querySelectorAll('model-viewer'))disposeViewer(old);
  for(const video of $('specimen').querySelectorAll('video'))video.pause();
  $('specimen').replaceChildren();
  $('source').replaceChildren();
  document.body.classList.toggle('has-refined-model',Boolean(item.poster));
  if (item.poster) $('specimen').after($('actions'));
  else $('actions').after($('specimen'));
  if (item.asset) {
    if (item.href) {
      const label = item.id === 'animal-cell' ? 'Open drawing and quiz tools' : 'Open guided walkthrough';
      $('actions').append(link(label,item.href,'secondary'));
    }
    if (item.id === 'animal-cell' && item.video) $('actions').append(link('Open camera walkthrough','/cr8zar/study/processes.html?process=animal-cell','secondary'));
    model(item);
    const label = el('p','Parts to find','topic');
    const list = el('ul', '', 'model-parts');
    list.append(...item.parts.map(part => el('li',part)));
    $('specimen').append(label,list);
    $('source').append((item.modelNote || 'Simplified teaching model.')+' ',link('Course reference',item.source));
  } else if (item.kind === 'Handout') {
    $('actions').append(link('Open study guide',item.href,'primary'),link('Open study activity',item.companion,'secondary'));
    if (item.related) $('actions').append(link('Related 3D model',itemHref(item.related),'secondary'));
  } else {
    $('actions').append(link(item.kind === 'Lesson' ? 'Open lesson' : 'Open 3D lesson',item.href,'primary'));
    if (item.galleryPoster && item.galleryAlt) {
      const preview = el('img', '', 'resource-preview');
      preview.src = item.galleryPoster;
      preview.alt = item.galleryAlt;
      preview.width = 960;
      preview.height = 600;
      preview.decoding = 'async';
      const posterLink = link('',item.href,'resource-preview-link');
      posterLink.append(preview);
      $('specimen').append(posterLink);
    }
    if (item.id === 'hela') {
      $('actions').append(link('Place HeLa in AR','/cr8zar/hela/?camera=1','secondary'));
    }
  }
  if (!item.asset && item.modelNote) $('source').append(item.modelNote);
  if (item.visualReference) $('source').append(' · ',link(item.visualReference.label,item.visualReference.href));
  for (const study of item.studyLinks || []) $('actions').append(link(study.label,study.href,'secondary'));
  if (item.handout) $('actions').append(link('Related handout',itemHref(item.handout.toLowerCase()),'secondary'));
  const canShareQR = hasQR(item);
  $('share').hidden = !canShareQR;
  $('share').open = false;
  if (canShareQR) {
    $('qr').src = qrAsset(item.id);
    $('qr').alt = 'QR code for ' + item.title;
    $('download').href = qrAsset(item.id);
  }
  if (navigate) {
    if (phone.matches) $('browse').open = false;
    $('title').focus();
  }
  drawResults();
}
for (const topic of [...new Set(items.map(i => i.topic))].sort()) $('topic').append(new Option(topic,topic));
for (const id of ['search','kind','topic']) $(id).addEventListener(id === 'search' ? 'input' : 'change',drawResults);
