function disposeModel(object) {
  const geometries=new Set(),materials=new Set(),textures=new Set(),skeletons=new Set();
  object?.traverse(node=>{
    if(!node.isMesh)return;
    if(node.skeleton&&!skeletons.has(node.skeleton)){skeletons.add(node.skeleton);node.skeleton.dispose();}
    if(!geometries.has(node.geometry)){geometries.add(node.geometry);node.geometry.dispose();}
    for(const material of [].concat(node.material)){
      if(materials.has(material))continue;
      materials.add(material);
      for(const value of Object.values(material))if(value?.isTexture&&!textures.has(value)){
        textures.add(value);value.dispose();value.source?.data?.close?.();
      }
      material.dispose();
    }
  });
}

