    <div class="tracked-ar-tools"><div class="tracked-ar-controls">
      <label>Model <select></select></label>
      <label>Speed <select data-speed><option value="1">Normal</option><option value="0.5">Half speed</option></select></label>
      <button type="button" data-action="play" disabled>Play motion</button>
      <button type="button" data-action="pause" disabled>Pause</button>
      <button type="button" data-action="replay" disabled>Replay</button>
    </div><div data-help></div></div>`;
  document.body.append(dialog);
  const surface=dialog.querySelector('.tracked-ar-view');
  const status=dialog.querySelector('[role=status]');
  const select=dialog.querySelector('select');
