  let current, sequence=0, resumePreview;
  function releaseModel(session){
    session.mixer?.stopAllAction();
    if(session.model)session.mixer?.uncacheRoot(session.model);
    disposeModel(session.model);
    session.pivot?.clear();
    session.model=session.mixer=session.action=undefined;
    session.dissolveMaterials=[];
  }
  function playback(name) {
    const action=current?.action;
    if(!action)return 'Choose a model with an animation and wait for it to load.';
    if(name==='pause'){
      action.paused=true;
      return 'I paused the animation.';
    }
    if(name==='replay' || !action.isScheduled() || action.time>=action.getClip().duration-.02)action.reset();
    action.paused=false;
    action.play();
    return name==='replay'?'I restarted the animation.':'I started the animation.';
