// Shared viewer lifecycle. Only active models remain in the GPU model cache.
import '/cr8zar/hela/assets/model-viewer.min.js';

export const isAndroid = /Android/i.test(navigator.userAgent);
const viewers = new WeakMap();
const nativeResumes = new Map();
const ModelViewer = customElements.get('model-viewer');
ModelViewer.modelCacheSize = 0;
const androidModels = isAndroid ? fetch('/cr8zar/android-ar-models.json?v=20261119')
  .then(response => {if(!response.ok)throw Error('AR compatibility unavailable');return response.json();})
  .then(data => data.models).catch(() => ({})) : Promise.resolve({});

function state(viewer) {
  if (!viewers.has(viewer)) {
    const record = {src:viewer.getAttribute('src'),holds:0,time:0,waiting:false,xrActive:false};
    viewers.set(viewer,record);
    viewer.addEventListener('ar-status',event => {
      record.xrActive = ['session-started','object-placed'].includes(event.detail.status);
    });
    viewer.addEventListener('load',() => {
      if (record.time > 0 && viewer.duration > 0) viewer.currentTime = Math.min(record.time,viewer.duration);
      record.time = 0;
    });
  }
  return viewers.get(viewer);
}

function restore(viewer,record) {
  if (record.holds || document.hidden || !record.src || !viewer.isConnected) return;
  record.waiting = false;
  if (viewer.getAttribute('src') !== record.src) viewer.setAttribute('src',record.src);
}

export function setViewerSource(viewer,src) {
  const record = state(viewer);
  if (record.src !== src) record.time = 0;
  record.src = src;
  if (!record.holds && !record.waiting && viewer.getAttribute('src') !== src) viewer.setAttribute('src',src);
  viewer.dispatchEvent(new Event('viewer-source-change'));
}

export function suspendViewer(viewer) {
  if (!viewer) return () => {};
  const record = state(viewer);
  if (!record.holds) {
    record.time = viewer.currentTime || 0;
    record.src = viewer.getAttribute('src') || record.src;
    viewer.pause();
    viewer.classList.remove('ready');
    viewer.removeAttribute('src');
    viewer.dispatchEvent(new Event('viewer-suspended'));
  }
  record.holds++;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    record.holds = Math.max(0,record.holds-1);
    record.waiting = document.hidden;
    restore(viewer,record);
  };
}

export function disposeViewer(viewer) {
  if (!viewer) return;
  const record = state(viewer);
  record.src = null;
  record.time = 0;
  viewer.pause();
  viewer.removeAttribute('src');
  nativeResumes.delete(viewer);
}

export function sceneViewerIntent(src,title,fallback = location.href) {
  const file = new URL(src,location.href);
  const back = new URL(fallback,location.href);
  if (!['https:','http:'].includes(file.protocol) || !['https:','http:'].includes(back.protocol)) throw Error('Invalid AR link');
  back.searchParams.set('ar-fallback','1');
  const params = new URLSearchParams({file:file.href,mode:'ar_preferred',title:title || 'BioBridge 3D model'});
  return 'intent://arvr.google.com/scene-viewer/1.0?'+params+'#Intent;scheme=https;package=com.google.ar.core;action=android.intent.action.VIEW;S.browser_fallback_url='+encodeURIComponent(back.href)+';end;';
}

export function configureViewer(viewer,{actions,status,title,src,androidHint,arButton} = {}) {
  const initial=state(viewer);
  if(src)initial.src=src;
  if (!actions) return;
  const retry = document.createElement('button');
  retry.type = 'button';
  retry.className = 'secondary';
  retry.textContent = 'Reload 3D model';
  retry.hidden = true;
  retry.addEventListener('click',() => {
    const record = state(viewer);
    if (!record.src || record.holds) return;
    viewer.pause();
    viewer.removeAttribute('src');
    record.time = 0;
    retry.hidden = true;
    if (status) status.textContent = 'Reloading the 3D model…';
    requestAnimationFrame(() => restore(viewer,record));
  });
  actions.append(retry);
  viewer.addEventListener('error',() => {retry.hidden = false;});
  viewer.addEventListener('load',() => {retry.hidden = true;});
  if (!isAndroid) return;
  // Scene Viewer rejects morph targets, multiple UV sets, and files above 15 MB.
  // WebXR renders the actual interactive scene, including the cell's dissolves.
  viewer.setAttribute('ar-modes','webxr');
  const native = document.createElement('a');
  native.className = 'secondary android-ar';
  native.textContent = 'Open Android AR';
  native.setAttribute('aria-label','Open this model in Android augmented reality');
  const hint=document.createElement('span');
  hint.className='status android-ar-help';
  hint.textContent=androidHint || 'Use Chrome on an ARCore-compatible Android phone for surface AR. The 3D view is also available without AR.';
  let compatibilityVersion=0;
  const refresh = async () => {
    const version=++compatibilityVersion;
    const src = state(viewer).src;
    native.hidden=true;native.removeAttribute('href');
    if (!src) return;
    const models=await androidModels;
    if(version!==compatibilityVersion || state(viewer).src!==src)return;
    const compatible=models[new URL(src,location.href).pathname]?.sceneViewerCompatible===true;
    viewer.setAttribute('ar-modes',compatible?'webxr scene-viewer':'webxr');
    if(compatible){native.href=sceneViewerIntent(src,title || viewer.getAttribute('alt'));native.hidden=false;}
    if(arButton){await viewer.updateComplete;arButton.hidden=!viewer.canActivateAR;}
  };
  native.addEventListener('click',() => {
    if(native.hidden)return;
    native.href=sceneViewerIntent(state(viewer).src,title || viewer.getAttribute('alt'));
    nativeResumes.get(viewer)?.();
    const release = suspendViewer(viewer);
    nativeResumes.set(viewer,release);
    // A missing intent handler must leave a working browser lesson.
    setTimeout(() => {if (!document.hidden && nativeResumes.get(viewer)===release) {release();nativeResumes.delete(viewer);}},2000);
  });
  viewer.addEventListener('viewer-source-change',refresh);
  viewer.addEventListener('load',refresh);
  refresh();
  actions.append(native,hint);
  const explainFallback = () => {
    if (new URL(location.href).searchParams.get('ar-fallback') === '1' && status) queueMicrotask(() => {
      status.textContent = 'Android AR is unavailable in this browser or on this device. Use Chrome and an updated Google Play Services for AR, or keep exploring in 3D.';
    });
  };
  viewer.addEventListener('load',explainFallback);
  explainFallback();
}

function resumeNative() {
  if (document.hidden) return;
  for (const release of nativeResumes.values()) release();
  nativeResumes.clear();
}
window.addEventListener('focus',resumeNative);
document.addEventListener('visibilitychange',() => {
  resumeNative();
  for (const viewer of document.querySelectorAll('model-viewer')) {
    const record = viewers.get(viewer);
    if (!record) continue;
    if (document.hidden && !record.xrActive) {
      viewer.pause();viewer.dispatchEvent(new Event('viewer-backgrounded'));
    }
    else restore(viewer,record);
  }
});

