$('part-select').addEventListener('change',e=>select(e.target.value));$('isolate').addEventListener('change',()=>select(selected));$('cutaway').addEventListener('change',e=>model?.cutaway(e.target.checked));
$('ask-part').addEventListener('click',()=>window.dispatchEvent(new CustomEvent('bridgeassist:open',{detail:{partId:selected,question:'Explain the structure and function of '+parts.find(p=>p.id===selected).name}})));
function setTool(value){tool=value;if(controls)controls.enabled=value==='select'&&!ar;document.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tool===value));$('tool-help').textContent=value==='select'?'Drag to rotate. Scroll or pinch to zoom. Select a part in the model or list.':value==='draw'?'Drag across a visible surface to draw a 3D mark. Marks stay attached when you rotate the cell.':'Select a surface to place a 3D circle around that location. Circles are annotations, not graded answers.'}
document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
$('clear-marks').addEventListener('click',()=>{if(model)while(model.marks.children.length){const o=model.marks.children[0];disposeMark(o);model.marks.remove(o)}markStatus()});
$('undo-mark').addEventListener('click',()=>{const o=model?.marks.children.at(-1);if(o){model.marks.remove(o);disposeMark(o)}markStatus()});
function markStatus(){if(model)$('mark-count').textContent=model.marks.children.length?model.marks.children.length+' annotation mark'+(model.marks.children.length===1?'':'s'):'No annotation marks'}
$('circle-selected').addEventListener('click',()=>{if(!model)return;if(ar&&!model.root.parent?.visible){$('tool-help').textContent='Point the camera at the cell image target before placing a circle.';return;}const object=model.parts.get(selected);const box=new THREE.Box3().setFromObject(object);const center=model.root.worldToLocal(box.getCenter(new THREE.Vector3()));const radius=Math.min(2.8,Math.max(.28,Math.max(box.getSize(new THREE.Vector3()).x,box.getSize(new THREE.Vector3()).y)*.55/model.root.scale.x));const q=currentCamera().quaternion.clone().premultiply(model.root.getWorldQuaternion(new THREE.Quaternion()).invert());const pts=Array.from({length:65},(_,i)=>new THREE.Vector3(Math.cos(i/64*Math.PI*2)*radius,Math.sin(i/64*Math.PI*2)*radius,.03).applyQuaternion(q).add(center));const circle=new THREE.Mesh(strokeGeometry(pts),new THREE.MeshBasicMaterial({color:0xe52626,depthTest:false,depthWrite:false,transparent:true}));circle.renderOrder=10;model.marks.add(circle);markStatus()});
function strokeGeometry(points){const pts=points.length>1?points:[points[0],points[0].clone().add(new THREE.Vector3(.0001,0,0))];return new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts),Math.max(8,Math.min(128,pts.length*3)),.016,6,false)}
function disposeMark(o){o.geometry?.dispose();o.material?.dispose()}
function applyLighting(){if(!lights)return;lights.key.intensity=Number($('light-intensity').value);lights.key.color.set($('light-color').value);const a=Number($('light-angle').value)*Math.PI/180;lights.key.position.set(Math.cos(a)*5,3,Math.sin(a)*5);lights.fill.intensity=$('light-preset').value==='contrast'?.35:1.5;$('light-value').value=Number($('light-intensity').value).toFixed(1)}
function preset(name){const values={studio:[2.5,45,'#ffffff'],soft:[1.5,70,'#fff2df'],contrast:[4,155,'#ffffff']};const v=values[name];if(v){$('light-intensity').value=v[0];$('light-angle').value=v[1];$('light-color').value=v[2]}applyLighting()}
$('light-preset').addEventListener('change',e=>preset(e.target.value));for(const id of ['light-intensity','light-angle','light-color'])$(id).addEventListener('input',()=>{$('light-preset').value='custom';applyLighting()});$('reset-light').addEventListener('click',()=>{$('light-preset').value='studio';preset('studio')});
document.querySelectorAll('[data-rotate]').forEach(b=>b.addEventListener('click',()=>{if(model)model.root.rotation.y+=Number(b.dataset.rotate)}));
function zoom(factor){if(ar){model.root.scale.setScalar(Math.min(.5,Math.max(.05,model.root.scale.x*factor)));return}if(camera){camera.position.multiplyScalar(1/factor);controls?.update()}}
$('zoom-in').addEventListener('click',()=>zoom(1.15));$('zoom-out').addEventListener('click',()=>zoom(.87));
function resetView(){if(!model)return;model.root.rotation.set(0,0,0);if(ar){model.root.scale.setScalar(.16);model.root.position.set(0,0,.35)}else{model.root.scale.setScalar(1);model.root.position.set(0,0,0);const aspect=$('cell-viewer').clientWidth/$('cell-viewer').clientHeight;const distance=Math.max(7.7,2.9/(Math.tan(THREE.MathUtils.degToRad(21))*aspect));camera.position.set(0,distance*.1,distance);controls.target.set(0,0,0);controls.update()}}
$('reset-view').addEventListener('click',resetView);
function currentCamera(){return ar?ar.camera:camera}
function hit(e){if(ar&&!model.root.parent?.visible)return null;const canvas=ar?ar.renderer.domElement:renderer.domElement;const box=canvas.getBoundingClientRect();const point=new THREE.Vector2((e.clientX-box.left)/box.width*2-1,-(e.clientY-box.top)/box.height*2+1);const ray=new THREE.Raycaster();ray.setFromCamera(point,currentCamera());return ray.intersectObjects(model.targets.filter(m=>m.parent.visible&&m.userData.partId!=='cytoplasm'&&m.userData.partId!=='membrane'),false)[0]}
function bindCanvas(canvas){canvas.addEventListener('pointerdown',e=>{pointerDown={x:e.clientX,y:e.clientY};if(tool==='select')return;const h=hit(e);if(!h)return;canvas.setPointerCapture(e.pointerId);const point=model.root.worldToLocal(h.point.clone());
 if(tool==='circle'){const pts=[];const normal=h.face.normal.clone().transformDirection(h.object.matrixWorld);const q=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,0,1),normal);const inv=model.root.getWorldQuaternion(new THREE.Quaternion()).invert();q.premultiply(inv);for(let i=0;i<=64;i++){const t=i/64*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(t)*.32,Math.sin(t)*.32,.035).applyQuaternion(q).add(point))}const line=new THREE.Mesh(strokeGeometry(pts),new THREE.MeshBasicMaterial({color:0xe52626,depthTest:false,depthWrite:false,transparent:true}));line.renderOrder=10;model.marks.add(line);markStatus();$('tool-help').textContent='Circle placed near '+(parts.find(p=>p.id===h.object.userData.partId)?.name||'the selected surface')+'. Rotate the cell to inspect it.';
 }else{activeMark=new THREE.Mesh(strokeGeometry([point]),new THREE.MeshBasicMaterial({color:0xe52626,depthTest:false,depthWrite:false,transparent:true}));activeMark.userData.points=[point];activeMark.renderOrder=10;model.marks.add(activeMark);markStatus()}});
 canvas.addEventListener('pointermove',e=>{if(!activeMark||tool!=='draw'||activeMark.userData.points.length>=512)return;const h=hit(e);if(!h)return;activeMark.userData.points.push(model.root.worldToLocal(h.point.clone()));activeMark.geometry.dispose();activeMark.geometry=strokeGeometry(activeMark.userData.points)});
 function finish(e){activeMark=null;if(tool==='select'&&pointerDown&&Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)<7){const h=hit(e);if(h)select(h.object.userData.partId)}pointerDown=null}
 canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',()=>{activeMark=null;pointerDown=null});
}
const cameraHelp=mountARAssist($('cell-camera-assist'),{
 intro:'Ask about the cell or say “reset view,” “show tracking guide,” or “close camera.”',
 actions:{
  reset:()=>{if(!model)return 'The cell model is still loading.';resetView();return 'I reset the cell view.';},
  stop:()=>{stopAR();return 'I stopped the camera.';},
  guide:()=> 'Point at the printed BioBridge cell image. Keep the whole image in the frame.'
 }
});
$('ar-start').addEventListener('click',async()=>{
 if(ar||arStarting||!model)return;arStarting=true;$('ar-start').disabled=true;$('viewer-status').textContent='Starting camera AR…';
 try{
  if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia)throw Error('Camera AR requires HTTPS and a browser with camera support.');
  const {MindARThree}=await import('../vendor/mindar-image-three.prod.js');
  document.body.classList.add('cell-ar-camera');
  ar=new MindARThree({container:$('cell-viewer'),imageTargetSrc:'handouts/cell-target.mind',maxTrack:1,uiLoading:'no',uiScanning:'no',uiError:'no'});
  const session=ar;
  renderer.setAnimationLoop(null);
  ar.renderer.localClippingEnabled=true;ar.renderer.setPixelRatio(Math.min(devicePixelRatio,androidPhone?1:1.5));ar.renderer.domElement.style.zIndex='2';ar.cssRenderer.domElement.style.pointerEvents='none';
  const anchor=ar.addAnchor(0);anchor.group.add(model.root);ar.scene.add(lights.group);model.root.scale.setScalar(.16);model.root.position.set(0,0,.35);model.root.rotation.set(0,0,0);controls.enabled=false;
  anchor.onTargetFound=()=>{$('viewer-status').textContent='AR target found · move your phone to explore'};
  anchor.onTargetLost=()=>{$('viewer-status').textContent='Point the camera at the printed cell image target'};
  await session.start();if(ar!==session){disposeCamera(session);return;}if(ar.video)ar.video.style.zIndex='0';renderer.domElement.hidden=true;bindCanvas(ar.renderer.domElement);ar.renderer.setAnimationLoop(()=>{if(ar===session){model.updateClipping();ar.renderer.render(ar.scene,ar.camera)}});$('ar-start').hidden=true;$('ar-stop').hidden=false;$('viewer-status').textContent='Point the camera at the printed cell image target';
 }catch(error){await stopAR();$('viewer-status').textContent=(error.name==='NotAllowedError'?'Camera permission was declined. The 3D lesson still works.':error.message||'Camera AR could not start. The 3D lesson still works.');}
 finally{arStarting=false;$('ar-start').disabled=false}
});
async function stopAR(){cameraHelp.close();document.body.classList.remove('cell-ar-camera');if(ar){const session=ar;ar=null;disposeCamera(session);scene.add(model.root);scene.add(lights.group)}if(renderer){renderer.domElement.hidden=false;controls.enabled=tool==='select';resetView();if(!document.hidden)renderer.setAnimationLoop(renderPreview)}$('ar-start').hidden=false;$('ar-stop').hidden=true;$('viewer-status').textContent='3D model · choose a part to explore'}
$('ar-stop').addEventListener('click',stopAR);window.addEventListener('pagehide',()=>{if(ar)stopAR()});
document.addEventListener('visibilitychange',()=>{
 if(document.hidden){renderer?.setAnimationLoop(null);if(ar)stopAR()}
 else if(renderer&&!ar)renderer.setAnimationLoop(renderPreview);
});
async function init(){
 try{const response=await fetch('data/study-content.json');if(!response.ok)throw Error();data=await response.json();parts=data.parts;for(const p of parts){const o=document.createElement('option');o.value=p.id;o.textContent=p.name;$('part-select').append(o)}select(selected)}catch{$('part-summary').textContent='Study content could not load. Please reload to try again.';return}
 try{
  THREE=await import('three');const [{OrbitControls},{buildCell}]=await Promise.all([import('../vendor/OrbitControls.js'),import('./cell-model.js')]);
  scene=new THREE.Scene();scene.background=new THREE.Color(0xeff2f3);camera=new THREE.PerspectiveCamera(42,1,.1,100);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.localClippingEnabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;$('cell-viewer').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','Animal cell. Use the cell part list and rotate buttons for keyboard control.');
  controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=false;controls.minDistance=4;controls.maxDistance=15;
  model=buildCell();scene.add(model.root);const lightGroup=new THREE.Group(),ambient=new THREE.HemisphereLight(0xf4f8ff,0x82949a,1.5),key=new THREE.DirectionalLight(0xffffff,2.5);lightGroup.add(ambient,key);scene.add(lightGroup);lights={group:lightGroup,fill:ambient,key};applyLighting();resetView();select(selected);bindCanvas(renderer.domElement);
  const resize=()=>{const el=$('cell-viewer');renderer.setSize(el.clientWidth,el.clientHeight);const previousAspect=camera.aspect;camera.aspect=el.clientWidth/el.clientHeight;if(camera.aspect<1&&previousAspect>=1){const distance=Math.max(7.7,2.9/(Math.tan(THREE.MathUtils.degToRad(21))*camera.aspect));camera.position.set(0,distance*.1,distance)}camera.updateProjectionMatrix();if(ar)ar.resize()};new ResizeObserver(resize).observe($('cell-viewer'));resize();
  renderer.setAnimationLoop(renderPreview);$('viewer-status').textContent='3D model · choose a part to explore';
  const activity=new URLSearchParams(location.search).get('activity');if(activity){const manifest=await fetch('data/handouts.json').then(r=>r.json());const item=manifest.items.find(i=>i.activity===activity);if(item){const note=document.createElement('p');note.className='concept-note';note.textContent='Handout companion: '+item.title+' · '+item.id+' · Version '+item.version;const a=document.createElement('a');a.href='credits.html?asset='+encodeURIComponent(item.id);a.textContent=' Sources & notes ↗';note.append(a);document.querySelector('.lesson-heading').append(note)}}if(activity?.includes('label'))setMode('labels');else if(activity?.includes('quiz'))setMode('quiz');
 }catch(error){$('viewer-error').hidden=false;$('ar-start').disabled=true;$('viewer-status').textContent='Text-based lesson available';$('tool-help').textContent='The text lesson, fill-in labels, and quiz remain available. 3D controls require a working WebGL view.';document.querySelectorAll('.viewer-tools button,.control-details input,.control-details select,#reset-light').forEach(b=>b.disabled=true);console.error('3D initialization',error)}
}
init();
